import json
import unittest
from pathlib import Path
from runner import ASSUMED_DRIVER_EYE_OFFSET_M,assumed_driver_viewpoint,check,control_for_time,frame_map_row
from cameras import camera_plan

ROOT=Path(__file__).resolve().parent
if not (ROOT/'config.json').exists():ROOT=ROOT.parent


class RunnerPreflightTest(unittest.TestCase):
    def setUp(self):self.base=json.loads((ROOT/'config.json').read_text())

    def test_all_twelve_unselected_native_preflights(self):
        suffixes=(self.base['case_suffix'],) if (ROOT/'obstruction.json').exists() else (
            'below_500_ft','at_500_ft','above_500_ft')
        for suffix in suffixes:
            for candidate in ('primary','fallback1','fallback2','fallback3'):
                with self.subTest(suffix=suffix,candidate=candidate):
                    config=dict(self.base,case_suffix=suffix,candidate_id=candidate,
                        case_id='training__C104538__NRS-484B-407__motor_vehicle_driver__'+suffix)
                    report=check(config)
                    self.assertEqual(report['camera_count'],4)
                    self.assertFalse(report['native_imported'])
                    self.assertFalse(report['physical_success_claimed'])

    def test_wrong_identity_and_capture_timing_rejected(self):
        for changed in (dict(case_suffix='invented'),dict(candidate_id='fallback4'),
                        dict(duration_s=12),dict(law_id='other')):
            with self.subTest(changed=changed):
                with self.assertRaises(ValueError):check(dict(self.base,**changed))

    def test_original_frame_identity(self):
        self.assertEqual(frame_map_row(0,101,.05),
                         {'video_frame':0,'native_frame':101,'carla_frame':101,'time_s':.05})
        for values in ((-1,101,.05),(0,-1,.05),(0,101,float('nan'))):
            with self.assertRaises(ValueError):frame_map_row(*values)

    def test_reversal_controls_are_requests(self):
        class Stub:
            @staticmethod
            def VehicleControl(**values):return values
        self.assertFalse(control_for_time(Stub,5)['reverse'] if 'reverse' in control_for_time(Stub,5) else False)
        self.assertTrue(control_for_time(Stub,12)['reverse'])
        self.assertGreater(control_for_time(Stub,20)['brake'],0)

    def test_camera_attachments_have_spawned_actor_roles(self):
        for suffix in ('below_500_ft','at_500_ft','above_500_ft'):
            for candidate in ('primary','fallback1','fallback2','fallback3'):
                mounts={view['attachment'] for view in camera_plan(suffix,candidate)}
                self.assertEqual(mounts,{'world','ego','reference_left','reference_right'})

    def test_driver_eye_assumption_is_independent_of_camera_fallback(self):
        class Location:
            x=10;y=20;z=3
        self.assertEqual(assumed_driver_viewpoint(Location()),
                         [10,20,3+ASSUMED_DRIVER_EYE_OFFSET_M])
        assert camera_plan('below_500_ft','fallback3')[1]['native_xyz_m'][2]!=\
            camera_plan('below_500_ft','primary')[1]['native_xyz_m'][2]


if __name__=='__main__':unittest.main()

import unittest
from engineering import CANDIDATES, check, plan
from geometry import OBSERVER_DISTANCES_FT


class CandidateEngineeringTest(unittest.TestCase):
    def test_distinct_fallbacks_and_controlled_context(self):
        result = check()
        self.assertTrue(result['passed'])
        self.assertEqual(result['construction_plans'],12)

    def test_each_case_has_four_unselected_plans(self):
        for suffix in OBSERVER_DISTANCES_FT:
            for candidate in CANDIDATES:
                with self.subTest(suffix=suffix,candidate=candidate):
                    value=plan(suffix,candidate)
                    self.assertFalse(value['selected'])
                    self.assertFalse(value['physical_trigger_measured'])

    def test_rejects_unknown_identity(self):
        with self.assertRaisesRegex(ValueError,'Unknown C104538'):
            plan('invented','primary')
        with self.assertRaisesRegex(ValueError,'Unknown C104538'):
            plan('below_500_ft','fallback4')

import math
import unittest
from cameras import camera_plan
from obstruction import check,placements


class PhysicalProposalTest(unittest.TestCase):
    def test_twelve_barrier_layouts_have_bounded_center_spacing(self):
        result=check()
        self.assertTrue(result['passed'])
        self.assertEqual(result['candidate_layouts'],12)
        self.assertFalse(result['native_actor_spawned'])

    def test_fallback2_halves_segment_spacing(self):
        for suffix in ('below_500_ft','at_500_ft','above_500_ft'):
            primary=placements(suffix,'primary')
            fallback=placements(suffix,'fallback2')
            self.assertGreater(len(fallback),len(primary))
            self.assertLess(fallback[1]['authored_segment_step_m'],
                            primary[1]['authored_segment_step_m'])

    def test_reference_camera_height_changes_only_for_fallback3(self):
        for suffix in ('below_500_ft','at_500_ft','above_500_ft'):
            baseline=camera_plan(suffix,'primary')
            raised=camera_plan(suffix,'fallback3')
            self.assertEqual([v['name'] for v in baseline],
                             [v['name'] for v in raised])
            for a,b in zip(baseline,raised):
                if a['name'].startswith('reference_'):
                    self.assertEqual(b['native_xyz_m'][2]-a['native_xyz_m'][2],2)
                else:self.assertEqual(a,b)
